import React from 'react';
import { questions } from '../data/questions';

function Summary({ answers }) {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Group answers by tags
  const tagGroups = {
    traditional: [],
    modern: [],
    minimal: [],
    luxury: []
  };

  Object.entries(answers).forEach(([index, answer]) => {
    if (answer?.tags) {
      answer.tags.forEach(tag => {
        if (tagGroups[tag]) {
          tagGroups[tag].push({
            question: questions[index].text,
            answer: answer.text
          });
        }
      });
    }
  });

  // Get dominant style
  const getDominantStyle = () => {
    const counts = Object.entries(tagGroups).map(([tag, items]) => ({
      tag,
      count: items.length
    }));
    return counts.sort((a, b) => b.count - a.count)[0].tag;
  };

  const dominantStyle = getDominantStyle();
  const styleNames = {
    traditional: "แบบดั้งเดิม",
    modern: "แบบร่วมสมัย",
    minimal: "แบบเรียบง่าย",
    luxury: "แบบหรูหรา"
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="bg-gradient-to-br from-gray-800 to-gray-900 rounded-2xl p-8 shadow-2xl">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-pink-600">
            สรุปการวางแผนงานศพของคุณ
          </h1>
          <div className="inline-block px-6 py-2 bg-gray-700 rounded-full">
            <span className="text-xl text-gray-300">
              สไตล์: {styleNames[dominantStyle]}
            </span>
          </div>
        </div>

        {/* Cost Summary */}
        <div className="bg-gray-700 rounded-xl p-6 mb-8 text-center">
          <h2 className="text-2xl font-semibold mb-2">งบประมาณโดยประมาณ</h2>
          <p className="text-3xl font-bold text-green-400">
            {totalCost.toLocaleString()} บาท
          </p>
        </div>

        {/* Style Highlights */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          {Object.entries(tagGroups).map(([tag, items]) => (
            items.length > 0 && (
              <div key={tag} className="bg-gray-700 rounded-xl p-6">
                <h3 className="text-xl font-semibold mb-4 text-gray-300">
                  {styleNames[tag]}
                </h3>
                <ul className="space-y-3">
                  {items.slice(0, 3).map((item, index) => (
                    <li key={index} className="text-gray-400">
                      {item.answer}
                    </li>
                  ))}
                </ul>
              </div>
            )
          ))}
        </div>

        {/* Key Decisions */}
        <div className="bg-gray-700 rounded-xl p-6">
          <h2 className="text-2xl font-semibold mb-4">การตัดสินใจสำคัญ</h2>
          <div className="space-y-4">
            {Object.entries(answers).map(([index, answer]) => (
              answer && (
                <div key={index} className="border-l-4 border-purple-500 pl-4">
                  <h3 className="text-lg font-medium text-gray-300">
                    {questions[index].text}
                  </h3>
                  <p className="text-gray-400 mt-1">
                    {answer.text}
                  </p>
                </div>
              )
            ))}
          </div>
        </div>

        {/* Footer */}
        <div className="mt-12 text-center">
          <p className="text-gray-400 italic">
            "การวางแผนงานศพคือการแสดงความรักครั้งสุดท้ายต่อคนที่คุณรัก"
          </p>
        </div>
      </div>
    </div>
  );
}

export default Summary;
